"use client";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";
import { useState, useTransition } from "react";
import { Clock } from "lucide-react";
import { saveFollowUpDays } from "@/lib/launch-actions";
import type { ActionResult } from "@/lib/errors";
import {
  useWorkspaceEntitlements,
  refreshWorkspaceAccess,
} from "@/components/workspace-quota";
import { useSuccessNotification } from "@/components/notifications";
import { Feedback } from "@/components/forms";
import { SettingsPanel } from "./SettingsPanel";
import { PremiumNotice } from "./PremiumNotice";
import { SavedStatus } from "./SavedStatus";
import styles from "./settings.module.css";
export function FollowUpReminders({ days }: { days: number }) {
  const upgrade = usePremiumUpgrade();
  const access = useWorkspaceEntitlements();
  const [value, setValue] = useState(days);
  const [result, setResult] = useState<ActionResult>();
  const [pending, start] = useTransition();
  const notify = useSuccessNotification();
  const locked = !access.features.followUpReminders;
  const unavailable =
    locked && access.reasons.followUpReminders !== "UPGRADE_REQUIRED";
  return (
    <SettingsPanel
      id="remind"
      title="Follow-up reminders"
      icon={Clock}
      description="History shows contacts due for a follow-up when no reply has been marked. Add them to your shortlist and approve each email in Compose. Reminders never send automatically."
    >
      {locked && (
        <PremiumNotice
          id="reminder-feature-lock"
          feature="Follow-up reminders"
        />
      )}
      <div className="mt-5 flex flex-wrap items-center gap-3">
        <label htmlFor="follow-up-days" className="text-sm font-semibold">
          Remind me after
        </label>
        {locked ? (
          <button
            id="follow-up-days"
            type="button"
            className="h-11.5 max-w-full cursor-pointer rounded-[var(--appearance-radius,_14px)] border border-[var(--settings-border)] bg-[var(--settings-inset)] px-4 text-[14px] text-[var(--settings-text)]"
            disabled={pending || unavailable}
            aria-describedby="reminder-feature-lock"
            aria-label="Follow-up reminder delay · Premium required"
            onClick={(event) =>
              upgrade({ feature: "reminders", trigger: event.currentTarget })
            }
          >
            {value ? `${value} days` : "Off"}
          </button>
        ) : (
          <select
            id="follow-up-days"
            className={`h-11.5 max-w-full rounded-[var(--appearance-radius,_14px)] [border:1px_solid_var(--settings-border)] [background:var(--settings-inset)] py-0 px-4 text-[var(--settings-text)] text-[14px]`}
            value={value}
            disabled={pending || unavailable}
            aria-describedby={locked ? "reminder-feature-lock" : undefined}
            onChange={(event) => setValue(Number(event.target.value))}
          >
            <option
              className="bg-[var(--settings-elevated)] text-[var(--settings-text)]"
              value={0}
            >
              Off
            </option>
            {[3, 7, 14].map((day) => (
              <option
                className="bg-[var(--settings-elevated)] text-[var(--settings-text)]"
                key={day}
                value={day}
              >
                {day} days
              </option>
            ))}
          </select>
        )}
        <button
          className={`${styles.primary} inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer button-interaction primary-action [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] shadow-none [border:1px_solid_transparent] text-[var(--primary-action-ink)] [background:var(--primary-action-gradient)] shadow-none`}
          disabled={pending || unavailable}
          onClick={() => {
            if (locked) return upgrade({ feature: "reminders" });
            start(async () => {
              try {
                const response = await saveFollowUpDays(value);
                setResult(response);
                if (response.ok) notify(response.message);
                else refreshWorkspaceAccess();
              } catch {
                setResult({ ok: false, message: "Could not save reminders." });
              }
            });
          }}
        >
          {pending ? "Saving…" : "Save reminders"}
        </button>
        <SavedStatus result={result} />
      </div>
      {result?.ok === false && <Feedback result={result} />}
    </SettingsPanel>
  );
}
